import type { EditorPage, OcrPageResult, OcrWord } from "@/lib/types";

export const OCR_RENDER_SCALE = 2.5;

export const OCR_LANGUAGES = [
  { code: "eng", label: "English" },
  { code: "spa", label: "Spanish" },
  { code: "fra", label: "French" },
  { code: "deu", label: "German" },
  { code: "ita", label: "Italian" },
  { code: "por", label: "Portuguese" },
  { code: "nld", label: "Dutch" },
  { code: "pol", label: "Polish" },
  { code: "rus", label: "Russian" },
  { code: "ukr", label: "Ukrainian" },
  { code: "ara", label: "Arabic" },
  { code: "hin", label: "Hindi" },
  { code: "jpn", label: "Japanese" },
  { code: "kor", label: "Korean" },
  { code: "chi_sim", label: "Chinese (Simplified)" },
  { code: "chi_tra", label: "Chinese (Traditional)" },
];

type PdfJsDoc = { getPage: (pageNumber: number) => Promise<any> };

export async function renderPageForOcr(pdf: PdfJsDoc, page: EditorPage) {
  const proxy = await pdf.getPage(page.sourceIndex + 1);
  const base = proxy.getViewport({ scale: 1, rotation: page.rotation });
  const viewport = proxy.getViewport({ scale: OCR_RENDER_SCALE, rotation: page.rotation });
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.ceil(viewport.width));
  canvas.height = Math.max(1, Math.ceil(viewport.height));
  const context = canvas.getContext("2d", { alpha: false, willReadFrequently: true });
  if (!context) throw new Error("Could not create an OCR rendering canvas.");
  context.fillStyle = "#ffffff";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await proxy.render({ canvasContext: context, viewport }).promise;
  return { canvas, baseWidth: base.width, baseHeight: base.height };
}

function rgbHex(r: number, g: number, b: number) {
  return `#${[r, g, b].map((value) => Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, "0")).join("")}`;
}

function sampleBackground(canvas: HTMLCanvasElement | undefined, left: number, top: number, width: number, height: number) {
  if (!canvas) return { backgroundColor: "#ffffff", textColor: "#111827" };
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) return { backgroundColor: "#ffffff", textColor: "#111827" };

  const margin = 4;
  const candidates = [
    [left - margin, top - margin],
    [left + width / 2, top - margin],
    [left + width + margin, top - margin],
    [left - margin, top + height / 2],
    [left + width + margin, top + height / 2],
    [left - margin, top + height + margin],
    [left + width / 2, top + height + margin],
    [left + width + margin, top + height + margin],
  ];

  let r = 0; let g = 0; let b = 0; let count = 0;
  for (const [rawX, rawY] of candidates) {
    const x = Math.max(0, Math.min(canvas.width - 1, Math.round(rawX)));
    const y = Math.max(0, Math.min(canvas.height - 1, Math.round(rawY)));
    const pixel = context.getImageData(x, y, 1, 1).data;
    r += pixel[0]; g += pixel[1]; b += pixel[2]; count++;
  }
  if (!count) return { backgroundColor: "#ffffff", textColor: "#111827" };
  r /= count; g /= count; b /= count;
  const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;

  let best = { r: luminance > 0.58 ? 17 : 248, g: luminance > 0.58 ? 24 : 250, b: luminance > 0.58 ? 39 : 252, distance: 0 };
  for (let gy = 1; gy <= 3; gy++) {
    for (let gx = 1; gx <= 7; gx++) {
      const x = Math.max(0, Math.min(canvas.width - 1, Math.round(left + (width * gx) / 8)));
      const y = Math.max(0, Math.min(canvas.height - 1, Math.round(top + (height * gy) / 4)));
      const pixel = context.getImageData(x, y, 1, 1).data;
      const distance = Math.hypot(pixel[0] - r, pixel[1] - g, pixel[2] - b);
      if (distance > best.distance) best = { r: pixel[0], g: pixel[1], b: pixel[2], distance };
    }
  }

  return {
    backgroundColor: rgbHex(r, g, b),
    textColor: best.distance > 45 ? rgbHex(best.r, best.g, best.b) : (luminance > 0.58 ? "#111827" : "#f8fafc"),
  };
}

export function parseTsvWords({
  tsv,
  pageId,
  canvasWidth,
  canvasHeight,
  baseWidth,
  baseHeight,
  canvas,
}: {
  tsv: string;
  pageId: string;
  canvasWidth: number;
  canvasHeight: number;
  baseWidth: number;
  baseHeight: number;
  canvas?: HTMLCanvasElement;
}): OcrWord[] {
  if (!tsv) return [];
  const scaleX = baseWidth / Math.max(1, canvasWidth);
  const scaleY = baseHeight / Math.max(1, canvasHeight);
  const lines = tsv.split(/\r?\n/);
  const words: OcrWord[] = [];

  for (let index = 1; index < lines.length; index++) {
    const columns = lines[index].split("\t");
    if (columns.length < 12 || columns[0] !== "5") continue;
    const text = columns.slice(11).join("\t").trim();
    if (!text) continue;
    const left = Number(columns[6]);
    const top = Number(columns[7]);
    const width = Number(columns[8]);
    const height = Number(columns[9]);
    const confidence = Number(columns[10]);
    if (![left, top, width, height].every(Number.isFinite) || width <= 0 || height <= 0) continue;
    const sampled = sampleBackground(canvas, left, top, width, height);
    words.push({
      id: `ocr_${pageId}_${index}`,
      pageId,
      text,
      originalText: text,
      edited: false,
      confidence: Number.isFinite(confidence) ? confidence : 0,
      x: left * scaleX,
      y: top * scaleY,
      width: width * scaleX,
      height: height * scaleY,
      lineKey: `${columns[2] || 0}:${columns[3] || 0}:${columns[4] || 0}`,
      backgroundColor: sampled.backgroundColor,
      textColor: sampled.textColor,
    });
  }
  return words;
}

export function ocrTextFromWords(words: OcrWord[]) {
  const lineOrder: string[] = [];
  const lines = new Map<string, OcrWord[]>();
  for (const word of words) {
    if (!lines.has(word.lineKey)) {
      lines.set(word.lineKey, []);
      lineOrder.push(word.lineKey);
    }
    lines.get(word.lineKey)!.push(word);
  }
  return lineOrder
    .map((key) => lines.get(key)!.sort((a, b) => a.x - b.x).map((word) => word.text).filter(Boolean).join(" "))
    .filter(Boolean)
    .join("\n");
}

export function makeOcrResult({
  page,
  language,
  text,
  words,
}: {
  page: EditorPage;
  language: string;
  text: string;
  words: OcrWord[];
}): OcrPageResult {
  return {
    pageId: page.id,
    language,
    text: text.trim() || ocrTextFromWords(words),
    words,
    recognizedAt: Date.now(),
  };
}
